#include <iostream>
#include <memory>
int main() {
    auto p = std::make_shared<int>(10);
    std::cout << p.use_count() << '\n';
    auto q = p;                       // 拷贝：强引用计数 +1
    std::cout << p.use_count() << '\n';
    std::cout << q.use_count() << '\n';
    q.reset();                        // 释放 q 的持有：强引用计数 -1
    std::cout << p.use_count() << '\n';
}
